DROP TABLE IF EXISTS `reproduksi_kelahiran`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `reproduksi_kelahiran` (
  `idkelahiran` int(11) NOT NULL AUTO_INCREMENT,
  `idsapi` int(11) DEFAULT NULL,
  `tanggal` date DEFAULT NULL,
  `xlaktasi` tinyint(4) DEFAULT NULL,
  `statuslahir` enum('single','kembar','abortus') DEFAULT NULL,
  `keterangan` varchar(255) DEFAULT NULL,
  `idpetugas` int(11) NOT NULL DEFAULT '0',
  `tglinput` date DEFAULT NULL,
  `idsapipedet` int(11) DEFAULT NULL,
  `statuslahirpedet` enum('Hidup','Mati','Abortus') DEFAULT NULL,
  `tagsapi` varchar(30) NOT NULL,
  `idfarm` varchar(10) NOT NULL,
  `idib` int(11) DEFAULT NULL,
  PRIMARY KEY (`idkelahiran`),
  UNIQUE KEY `unik` (`idsapi`,`tanggal`),
  KEY `petugas_kelahiran` (`idpetugas`),
  KEY `sapi_id` (`idsapi`),
  KEY `tanggal` (`tanggal`)
) ENGINE=InnoDB AUTO_INCREMENT=1555 DEFAULT CHARSET=latin1;
