--
-- Table structure for table `sapi`
--

DROP TABLE IF EXISTS `sapi`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sapi` (
  `idsapi` int(11) NOT NULL AUTO_INCREMENT,
  `idfarm` varchar(7) DEFAULT NULL,
  `tagsapi` varchar(100) DEFAULT NULL,
  `idbangsa` tinyint(4) DEFAULT NULL,
  `kelamin` enum('Jantan','Betina','') DEFAULT NULL,
  `tipesapi` enum('IB','ET','Alam','Semen','Dam','Sire') DEFAULT NULL,
  `namasapi` varchar(100) DEFAULT NULL,
  `tgllahir` datetime DEFAULT NULL,
  `bobotlahir` double DEFAULT NULL,
  `status` enum('hidup','mati','afkir','dijual','','mutasi','tidakjelas') DEFAULT NULL,
  `idkandang` int(11) DEFAULT NULL,
  `is_uzur` int(1) NOT NULL DEFAULT '0',
  `is_kso` int(1) NOT NULL DEFAULT '0',
  `is_balai` int(1) NOT NULL DEFAULT '0',
  `is_vbc` int(1) NOT NULL DEFAULT '0',
  `statuspc` enum('PC','DC','ANAK DC','','-') DEFAULT NULL,
  `tglinput` datetime DEFAULT NULL,
  `tglsertifikat` date DEFAULT NULL,
  `tgllspro` date DEFAULT NULL,
  `idasal` tinyint(4) DEFAULT NULL,
  `idsire` int(11) DEFAULT NULL,
  `kodesire` varchar(20) DEFAULT NULL,
  `noregsire` varchar(20) DEFAULT NULL,
  `namasire` varchar(100) DEFAULT NULL,
  `iddam` int(11) DEFAULT NULL,
  `kodedam` varchar(20) DEFAULT NULL,
  `noregdam` varchar(20) DEFAULT NULL,
  `namadam` varchar(100) DEFAULT NULL,
  `milkbv` int(11) DEFAULT NULL,
  `fatbv` int(11) DEFAULT NULL,
  `proteinbv` int(11) DEFAULT NULL,
  `milk` int(11) DEFAULT NULL,
  `fat` int(11) DEFAULT NULL,
  `protein` int(11) DEFAULT NULL,
  PRIMARY KEY (`idsapi`),
  UNIQUE KEY `idfarm` (`idfarm`,`tagsapi`),
  KEY `farm_sapi` (`idfarm`),
  KEY `idbangsa` (`idbangsa`),
  KEY `tagsapi` (`tagsapi`),
  KEY `namasapi` (`namasapi`),
  KEY `idsapi` (`idsapi`),
  KEY `status` (`status`),
  CONSTRAINT `sapi_ibfk_1` FOREIGN KEY (`idfarm`) REFERENCES `farm` (`idfarm`),
  CONSTRAINT `sapi_ibfk_2` FOREIGN KEY (`idbangsa`) REFERENCES `bangsasapi` (`idbangsa`)
) ENGINE=InnoDB AUTO_INCREMENT=1438 DEFAULT CHARSET=latin1;
