DROP TABLE IF EXISTS `sapi_potong`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `sapi_potong` (
  `nomor` smallint(6) NOT NULL,
  `eartag` varchar(10) DEFAULT NULL,
  `jenis` varchar(20) DEFAULT NULL,
  `rumpun` varchar(20) DEFAULT NULL,
  `asal` varchar(20) DEFAULT NULL,
  `kelamin` varchar(10) DEFAULT NULL,
  `tgllahir` date DEFAULT NULL,
  PRIMARY KEY (`nomor`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
